+from pathlib import Path
+import re
+
+p = Path('kalman/index.html')
+s = p.read_text(encoding='utf-8')
+s = s.replace('<script defer src="model.js"></script>', '<script defer src="model.js"></script><script defer src="controls.js"></script>')
+s = s.replace('Take the controls and discover how a Kalman filter navigates the unknown.</p>', 'The white line shows where it really is; amber circles are noisy fixes; teal is its best estimate.</p><a class="lesson-link" href="#worked-title">Follow one correction ↓</a>')
+s = s.replace('</div>\n      <div class="scene-wrap">', '</div>\n      <div class="inspection"><label for="scrub">Inspect mission time <output id="scrub-time" aria-live="off">0.0 / 60.0 s</output></label><div><input id="scrub" type="range" min="0" max="300" step="1" value="0" aria-valuetext="0.0 seconds of 60.0 seconds"><button id="end">To end</button></div><p>Drag or use arrow keys to inspect while paused. <a href="#worked-title">Follow one correction ↓</a></p></div>\n      <div class="scene-wrap">')
+s = s.replace('Random disturbances, unbiased fixes. The default Q and R match the actual noise.', 'Random disturbances, unbiased fixes. R and q match the actual random noise variances.')
+s = re.sub(r'(<input id="[rq]-noise" type="range") min="[^"]+" max="[^"]+" step="[^"]+" value="[^"]+"', r'\1 min="0" max="322" step="1" value="0"', s)
+s = s.replace('Tuning replays the <strong>same sensor data</strong>.</p></fieldset>', 'Tuning replays the <strong>same sensor data</strong>. q = 0 is the leftmost setting.</p><button id="match" class="wide">Match actual noise</button></fieldset>')
+s = s.replace('The default values are rounded to four significant figures.', 'Logarithmic tuning uses four significant figures; Match actual noise keeps the exact squared standard deviations, including q = 0.')
+s = s.replace('<details class="model-details panel" open>', '<details class="model-details panel">')
+s = s.replace('Depth advances using vertical velocity and known acceleration. Uncertain acceleration adds covariance Q.', 'First, use the last depth, speed and commanded acceleration to predict where the robot will be. Uncertain acceleration widens the range of plausible depths.')
+s = s.replace('The innovation is the fix minus predicted depth. Gain K balances predicted uncertainty against assumed sensor variance R.', 'Then listen to the sensor. How far is its fix from the prediction? Gain K is the fraction of that gap to follow: larger R means less trust in the fix.')
+s = s.replace('Move depth and velocity by K·y. A missing fix skips correction; the prediction and its growing uncertainty remain.', 'Move the estimate partway toward the fix. The same correction also adjusts speed. With no fix, keep the prediction and its growing uncertainty.')
+s = re.sub(r'(<code>.*?</code>)', r'<details class="equations"><summary>Show the equations</summary>\1</details>', s, flags=re.S)
+old = '<p class="lesson-prompt"><strong>Try this:</strong> Run dropout to 20 s. Step forward and watch the interval widen. Then save a baseline and increase R: why does the filter hesitate when fixes return?</p>'
+new = '''<fieldset class="learner"><legend>Predict before you inspect</legend><p>Select Dropout and inspect 19.8 s, 35.8 s and 36 s. What happens to assumed depth uncertainty while fixes are missing?</p><label><input type="radio" name="dropout-answer" value="grow"> It grows as prediction continues</label><label><input type="radio" name="dropout-answer" value="shrink"> It shrinks because the sensor is silent</label><label><input type="radio" name="dropout-answer" value="stop"> The robot stops until a fix returns</label><button id="check-answer">Check my prediction</button><p id="answer-feedback" role="status" aria-live="polite"></p></fieldset>'''
+assert old in s
+s = s.replace(old, new)
+s = re.sub(r'<output(?![^>]*aria-live)', '<output aria-live="off"', s)
+# A failed or unavailable script leaves every interactive action unavailable.
+s = re.sub(r'<(button|input|select)\b[^>]*>', lambda m: m.group(0) if 'disabled' in m.group(0) else m.group(0)[:-1] + ' disabled>', s)
+p.write_text(s, encoding='utf-8')
+
+p = Path('kalman/styles.css')
+s = p.read_text(encoding='utf-8')
+s += '''
+/* Inspection stays with transport above the scene at every width. */
+.inspection{padding:10px 20px;border-bottom:1px solid var(--edge)}
+.inspection>label{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:.75rem}
+.inspection>div{display:flex;gap:12px;align-items:center}.inspection input{flex:1;min-width:0}.inspection button{flex:none}
+.inspection p{font-size:.7rem;color:var(--muted);margin:2px 0 0}.inspection p a,.lesson-link{display:inline-flex;align-items:center;min-height:44px;color:var(--teal)}
+.lesson-link{font-size:.8rem;margin-top:5px}fieldset .wide{width:100%;margin-top:4px}
+.learner{margin:22px 0 0;padding-top:16px}.learner legend{color:var(--teal);font-size:.8rem}
+.learner label{display:flex;align-items:center;justify-content:flex-start;min-height:44px;gap:12px;font-size:.8rem;cursor:pointer}
+.learner input{width:18px;height:18px;flex:none;accent-color:var(--teal)}.learner button{margin-top:12px}.learner p:empty{display:none}
+.equations summary{padding:8px 0;font-size:.75rem}.equations code{display:block;padding-bottom:10px}
+#worked-title{scroll-margin-top:20px}
+@media(max-width:760px){.inspection{padding:10px 14px}.learning{gap:22px}.lesson-cards article{gap:14px}}
+'''
+p.write_text(s, encoding='utf-8')
+
+Path('work/goal-loop-state.md').write_text('''# Goal review progress
+
+Goal: Integrate the final Abyss robotics Kalman lab per .design-input/GOAL.md.
+Completed cycles: 0 of 3. Cycle 1 building; latest score: not assessed.
+Acceptance: cinematic foundation; physical silent controls; paused scrub/end; exact noise match; truthful help; novice lesson and dropout feedback; complete plot bounds; guarded numerical inputs; no-JS fallback; full regression and fresh three-size browser checks.
+Changes: kalman/{index.html,styles.css,app.js,model.js,controls.js}.
+Remaining: tests, browser journeys, evidence, DELIVERY.md, checker review.
+''', encoding='utf-8')

